# END ENCODED CAP MESH DATA

def legacy_cap_face(kind):
    """Decode one immutable binary STL into the original triangulation-only Face.

    OCCT RWStl defaults merge only exactly equal XYZ coordinates and preserve
    triangle winding. Reproduce that indexing in memory, without temporary files.
    STL facet normals/attribute bytes remain in CAP_STL_BYTES, not analytic CAD.
    """
    raw = CAP_STL_BYTES[kind]
    provenance = CAP_ASSET_PROVENANCE[kind]
    if hashlib.sha256(raw).hexdigest() != provenance['sha256']:
        raise ValueError(f"Changed immutable legacy cap asset: {kind}")
    if len(raw) < 84:
        raise ValueError(f"Truncated binary STL asset: {kind}")
    count = struct.unpack_from('<I', raw, 80)[0]
    if count != provenance['triangles'] or len(raw) != 84 + 50 * count:
        raise ValueError(f"Invalid binary STL record count: {kind}")
    node_ids, triangles = {}, []
    for record in struct.iter_unpack('<12fH', memoryview(raw)[84:]):
        ids = []
        for offset in (3, 6, 9):
            xyz = record[offset:offset + 3]
            if not all(math.isfinite(value) for value in xyz):
                raise ValueError(f"Non-finite binary STL vertex: {kind}")
            if xyz not in node_ids:
                node_ids[xyz] = len(node_ids) + 1
            ids.append(node_ids[xyz])
        if len(set(ids)) != 3:
            raise ValueError(f"Degenerate binary STL triangle: {kind}")
        triangles.append(ids)
    mesh = Poly_Triangulation(len(node_ids), len(triangles), False, False)
    for xyz, index in node_ids.items():
        mesh.SetNode(index, gp_Pnt(*xyz))
    for index, ids in enumerate(triangles, 1):
        mesh.SetTriangle(index, Poly_Triangle(*ids))
    face = TopoDS_Face()
    BRep_Builder().MakeFace(face, mesh)
    return Face.cast(face)


# shell: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/shell.py
table_MIN = (Align.MIN, Align.MIN, Align.MIN)


table_CYL = (Align.CENTER, Align.CENTER, Align.MIN)


def table_box(x0, x1, y0, y1, z0, z1):
    return Pos(x0, -y1, z0) * Box(x1-x0, y1-y0, z1-z0, align=table_MIN)


def table_cyl(x, y, z0, z1, r0, r1=None):
    r1 = r0 if r1 is None else r1
    obj = Cylinder(r0, z1-z0, align=table_CYL) if r0 == r1 else Cone(r0, r1, z1-z0, align=table_CYL)
    return Pos(x, -y, z0) * obj


def table_horizontal(x, y, z, radius, length):
    return Pos(x, -y, z) * Rot(90, 0, 0) * Cylinder(radius, length, align=table_CYL)


def table_primitive(p):
    kind, (x, y, z), size = p
    if kind == 0:
        w, h, d = size
        return Pos(x, y, z) * Box(w, h, d, align=table_MIN)
    if kind == 1:
        r0, r1, h = size
        return Pos(x, y, z) * (Cylinder(r0, h, align=table_CYL) if r0 == r1 else Cone(r0, r1, h, align=table_CYL))
    assert kind == 2, p
    w, h, r, height = size
    assert 0 < r <= min(w, h)/2
    pieces = []
    if w > 2*r:
        pieces.append(Pos(x-w/2+r, y-h/2, z) * Box(w-2*r, h, height, align=table_MIN))
    if h > 2*r:
        pieces.append(Pos(x-w/2, y-h/2+r, z) * Box(w, h-2*r, height, align=table_MIN))
    for sx in (-1, 1):
        for sy in (-1, 1):
            pieces.append(Pos(x+sx*(w/2-r), y+sy*(h/2-r), z) * Cylinder(r, height, align=table_CYL))
    result = pieces[0]
    for piece in pieces[1:]:
        result = result + piece
    return result


def table_group(csg):
    name, transform, additions, cuts = csg
    assert additions, name
    result = table_primitive(additions[0])
    for p in additions[1:]:
        result = result + table_primitive(p)
    for p in cuts:
        result = result - table_primitive(p)
    # Map table Y to CAD Y without applying a non-rigid reflection as a location.
    a, b = transform[0][:2]
    c, d = transform[1][:2]
    determinant = a*d - b*c
    assert math.isclose(abs(determinant), 1, abs_tol=1e-9), name
    if determinant > 0:
        result = result.mirror(Plane.XZ)
    angle = math.degrees(math.atan2(-c, a))
    result = result.moved(Location((transform[0][3], -transform[1][3], transform[2][3]), angle))
    assert result.is_valid and result.volume > 0, name
    return result


def table_valid(shape, label):
    assert shape is not None and shape.is_valid and len(shape.solids()) == 1 and shape.volume > 0, label
    return shape


def table_edge_points(edge):
    return [edge.position_at(t) for t in (0, .25, .5, .75, 1)]

# panels: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/panels.py
panel_MIN = (Align.MIN, Align.MIN, Align.MIN)


panel_CMIN = (Align.CENTER, Align.CENTER, Align.MIN)


def panel_box(x0, x1, y0, y1, z0, z1):
    return Pos(x0, y0, z0) * Box(x1-x0, y1-y0, z1-z0, align=panel_MIN)


def panel_cylinder(x, y, z, radius, height):
    return Pos(x, y, z) * Cylinder(radius, height, align=panel_CMIN)


def panel_polygon(points, z, height):
    return Pos(0, 0, z) * extrude(Polygon(*points, align=None), amount=height, dir=(0, 0, 1))


def panel_profile(row, z=17, height=5):
    name, x, y, kind, w, h, r, _ = row
    if name.startswith('T'):
        a = 7.2 + 1.6 * math.sqrt(5)
        sign = 1 if int(name[1:]) % 2 else -1
        return panel_polygon([(x+sign*u, -y+sign*v) for u, v in
                        [(-a, 0), (4, (a+4)/2), (4, -(a+4)/2)]], z, height)
    if kind == 'circle':
        return panel_cylinder(x, -y, z, w/2, height)
    if kind == 'rect':
        sketch = Rectangle(w, h)
    elif kind == 'slot':
        sketch = SlotOverall(max(w, h), min(w, h), rotation=90 if h > w else 0)
    else:
        sketch = RectangleRounded(w, h, r)
    return Pos(x, -y, z) * extrude(sketch, amount=height)


def panel_edge_points(edge):
    return [edge.position_at(t) for t in (0, .25, .5, .75, 1)]


def panel_top_edges(part, predicate, z=20):
    return [e for e in part.edges() if all(abs(p.Z-z) < 1e-5 and predicate(p.X, p.Y)
                                           for p in panel_edge_points(e))]


def panel_chamfer_edges(part, predicate):
    edges = panel_top_edges(part, predicate)
    if edges:
        return chamfer(edges, .8)
    raise ValueError('Expected top chamfer edges not found')


def panel_cap_edge(row, x, y):
    name, cx, cy, kind, w, h, r, _ = row
    u, v = x-cx, y+cy
    if name.startswith('T'):
        sign = 1 if int(name[1:]) % 2 else -1
        u, v = sign*u, sign*v
        a = 7.2 + 1.6*math.sqrt(5)
        distances = [u-4, (-u+2*v-a)/math.sqrt(5), (-u-2*v-a)/math.sqrt(5)]
        return max(distances) <= 1e-5 and min(abs(d) for d in distances) < 1e-5
    if kind == 'circle':
        return abs(math.hypot(u, v)-w/2) < 1e-5
    qx, qy = abs(u)-(w/2-r), abs(v)-(h/2-r)
    return abs(math.hypot(max(qx, 0), max(qy, 0))+min(max(qx, qy), 0)-r) < 1e-5


def panel_load_data():
    """Fresh effective panel inputs; no predecessor files are read."""
    moves = {r['id']: r['new_XY'] for r in deepcopy(CONTROL_MOVES)}
    return (deepcopy(PANEL_DATA), None, deepcopy(PANEL_FADER_RECESSES),
            deepcopy(PANEL_MARKS), moves)



def panel_section(x, width, points):
    return extrude(Plane.YZ.offset(x) * Polygon(*points, align=None), amount=width, dir=(1, 0, 0))

# controls: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/controls.py
def retainer_primitive(spec):
    kind, origin, size = spec
    x, y, z = origin
    if kind == 0:
        return Solid.make_box(*size, plane=Plane(origin=(x, y, z)))
    if kind == 1:
        r0, r1, height = size
        plane = Plane(origin=(x, y, z))
        if r0 == r1:
            return Solid.make_cylinder(r0, height, plane=plane)
        return Solid.make_cone(r0, r1, height, plane=plane)
    if kind == 2:
        width, height, radius, depth = size
        return extrude(RectangleRounded(width, height, radius), amount=depth).moved(
            Location((x, y, z))
        )
    raise ValueError(f"Unsupported control CSG primitive: {kind}")


def retainer_local_retainer(csg):
    _, _, additions, cuts = csg
    positive = [retainer_primitive(spec) for spec in additions]
    negative = [retainer_primitive(spec) for spec in cuts]
    with BuildPart() as part:
        insert(positive)
        insert(negative, mode=Mode.SUBTRACT)
    return part.part

# reference_controls: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/reference_controls.py
def control_reference_build():
    rows = deepcopy(CONTROL_SOURCE_ROWS)
    rows = [row for row in rows if "retainer" not in row["id"].lower()]
    if len(rows) != 49:
        raise ValueError(f"Expected 49 control bodies; got {len(rows)}")
    result = {}
    for row in rows:
        name, transform = row["owner"], row["CSG"][1]
        cuts = []
        if name.startswith(("B", "T")):
            additions = [[0, [-6, -6, 0], [12, 12, 4.3]]]
        elif name.startswith("P"):
            additions = [[0, [-5.7, -5.5, 0], [11.4, 12.5, 6.8]]]
        elif name.startswith("F"):
            additions = [[0, [-30, -4.5, 0], [60, 9, 6]], [0, [-2, -.5, 6], [4, 1, 15]]]
        elif name == "E01":
            additions = [[0, [-5.9, -7, 0], [11.8, 14.5, 6.5]], [1, [0, 0, 6.5], [3.5, 3.5, 7]], [1, [0, 0, 13.5], [3, 3, 8]]]
            cuts = [[0, [-5, 1.5, 14.5], [10, 3.5, 7.01]]]
        else:
            raise ValueError(f"Unknown control: {name}")
        solid = table_group([name, transform, additions, cuts])
        solid.label = name + " incomplete purchased control reference"
        result[name + "-BODY-REF"] = solid
        if name.startswith(("B", "T")):
            vertices = []
            for x, y in ((-1.9, -1.9), (-1.9, 1.9), (1.9, 1.9), (1.9, -1.9)):
                coords = (x, y, 7.3)
                xyz = [sum(transform[i][j]*coords[j] for j in range(3)) + transform[i][3] for i in range(3)]
                vertices.append((xyz[0], -xyz[1], xyz[2]))
            face = Face(Wire.make_polygon(vertices, close=True))
            face.label = name + " nominal free plunger tip plane reference"
            result[name + "-TIP-REF"] = face
    return result

# reference_equipment: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/reference_equipment.py
equipment_reference_CYL = (Align.CENTER, Align.CENTER, Align.MIN)


def equipment_reference_axis_y(x, y, z, radius, length):
    return Pos(x, y, z) * Rot(-90, 0, 0) * Cylinder(radius, length, align=equipment_reference_CYL)


def equipment_reference_build():
    b22 = {"devices": EQUIPMENT_DEVICES}
    data = {"b15_controllers": EQUIPMENT_CONTROLLERS}
    result = {}
    for dev in b22["devices"]:
        x, y = dev["centre_XY"]
        w, h = dev["size_XY"]
        z0, z1 = dev["body_Z"] if dev["id"] == "PSU" else (dev["PCB_underside_Z"]-dev["below_PCB"], dev["PCB_underside_Z"]+dev["above_PCB"])
        result[dev["id"] + "-envelope"] = table_box(x-w/2, x+w/2, y-h/2, y+h/2, z0, z1)
    for name, (x, y), (w, h), (z0, z1) in data["b15_controllers"]:
        result[name + "-envelope"] = table_box(x-w/2, x+w/2, y-h/2, y+h/2, z0, z1)
    result["J01-body"] = equipment_reference_axis_y(101, -298, 10, 4.075, 11.8) + equipment_reference_axis_y(101, -302.5, 10, 3, 4.5)
    result["J01-nut"] = equipment_reference_axis_y(101, -301.8, 10, 4, 1.8) - equipment_reference_axis_y(101, -301.81, 10, 3, 1.82)
    a = math.radians(49)
    c, s = math.cos(a), math.sin(a)
    cy, height = 96-40*c, 18+40*s
    points = [(300+u, -cy-c*v, height-s*v) for u, v in ((-138, -38), (-138, 38), (138, 38), (138, -38))]
    result["D01-front-plane"] = Face(Wire.make_polygon(points, close=True))
    result["RCA-front-plane"] = Face(Wire.make_polygon([(x, 0, z) for x, z in ((28.85, .05), (28.85, 19.95), (80.55, 19.95), (80.55, .05))], close=True))
    for name, part in result.items():
        part.label = name + " incomplete reference / not vendor geometry"
    return result

# hardware: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/hardware.py
def fastener_cylinder(radius, height, bottom):
    return Pos(0, 0, bottom) * Cylinder(radius, height, align=(Align.CENTER, Align.CENTER, Align.MIN))


def fastener_socket_screw(radius, length, head_radius, head_height):
    return fastener_cylinder(radius, length, -length) + fastener_cylinder(head_radius, head_height, 0)


def fastener_countersunk(radius, length, head_radius):
    height = head_radius - radius
    cone = Pos(0, 0, -height) * Cone(radius, head_radius, height, align=(Align.CENTER, Align.CENTER, Align.MIN))
    return fastener_cylinder(radius, length, -length) + cone

# display_toes: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/display_toes.py
display_toe_MIN = (Align.MIN, Align.MIN, Align.MIN)


display_toe_CYL = (Align.CENTER, Align.CENTER, Align.MIN)


def display_toe_build():
    toe = Pos(136.5, 20, -21) * Box(7.7, 8, 3, align=display_toe_MIN)
    toe += Pos(136.5, 20, -18) * Box(1, 8, 1, align=display_toe_MIN)
    toe -= Pos(140.7, 24, -21.1) * Cylinder(1.7, 3.2, align=display_toe_CYL)
    angle = radians(49)
    c, s = cos(angle), sin(angle)
    cy, height = 96 - 40*c, 18 + 40*s
    result = {}
    for side, row in product((-1, 1), repeat=2):
        local = toe.mirror(Plane.XZ) if side*row > 0 else toe
        frame = Plane(origin=(300, -cy, height), x_dir=(side, 0, 0), z_dir=(0, -s, c))
        part = local.moved(frame.location)
        key = f"D01-toe-{side}-{row}"
        part.label = key + " printed B24-build123d01 DRAFT"
        result[key] = part
    return result

# caps: retained constructive functions from BASELINE/models/enclosure/B24/BUILD123D/caps.py
def cap_build(definitions=None):
    """Place canonical cap prototypes at the original 49 poses."""
    if definitions is None:
        definitions = {kind: legacy_cap_face(kind) for kind in CAP_STL_BYTES}
    rows = CAP_INVENTORY
    if len(rows) != 49:
        raise ValueError(f"Expected 49 installed caps, got {len(rows)}")
    result = {}
    for row in rows:
        p = row["pose"]
        frame = Plane(origin=(p[3]*10, p[7]*10, p[11]*10), x_dir=(p[0], p[4], p[8]), z_dir=(p[2], p[6], p[10]))
        part = definitions[row["component"].split()[0]].moved(frame.location)
        part.label = row["occurrence"] + " / immutable mesh reference"
        result[row["id"]] = part
    return result


# b26_shell: retained constructive functions from BASELINE/models/enclosure/B26/BUILD123D03/b26_shell.py
enclosure_REAR_TOP = 23 + 80 * math.sin(math.radians(49))


def enclosure_joints():
    definition = RETAINED_JOINTS
    joints = []
    for source in definition['retained_joints'] + definition['added_joints']:
        x, y = source['centre']
        joints.append((source['id'], source['normal'], x, y + 20))
    joints.extend((('J15', 'X', 220, 14), ('J16', 'X', 380, 14)))
    assert len(joints) == 16
    return joints

# b26_controls: retained constructive functions from BASELINE/models/enclosure/B26/BUILD123D03/b26_controls.py
def control_source_rows():
    source = deepcopy(CONTROL_SOURCE_ROWS)
    if len(source) != 98 or len({r["id"] for r in source}) != 98:
        raise ValueError("Expected 98 unique B24 fixed/retainer control groups")
    return source


def control_targets(source):
    coordinates = CONTROL_COORDINATES
    moves = {r["id"]: r for r in deepcopy(CONTROL_MOVES)}
    targets = {}
    for row in source:
        owner = row["owner"]
        x, y = coordinates[owner]
        old = row["CSG"][1]
        if owner in moves:
            move = moves[owner]
            if not all(math.isclose(a, b, abs_tol=1e-7) for a, b in zip((x, y), move["old_XY"])):
                raise ValueError(f"R12/B24 move mismatch: {owner}")
            baseline = move["new_XY"]
        else:
            baseline = (x, y)
        if not all(math.isclose(a, b, abs_tol=1e-7) for a, b in zip((old[0][3], old[1][3]), baseline)):
            raise ValueError(f"B24 control pose mismatch: {owner}")
        if owner in ("B23", "B24"):
            target = (x, 255.0)
        elif owner in ("E01", "T01", "T02"):
            target = (x, y + 20.0)
        else:
            target = (baseline[0], y + 20.0)
        if owner in targets and targets[owner] != target:
            raise ValueError(f"Inconsistent owner target: {owner}")
        targets[owner] = target
    if len(targets) != 49:
        raise ValueError(f"Expected 49 controls, found {len(targets)}")
    return targets


def control_move_fader_ends(csg):
    # B26-DETAIL-01 sheet 3: rigidly move end-side primitives, not rails.
    for primitives in csg[2:4]:
        for kind, origin, size in primitives:
            u = origin[0]
            if kind == 0:
                low, high = u, u + size[0]
                if low < 0 < high:
                    if not math.isclose(low, -high, abs_tol=1e-7):
                        raise ValueError(f"Ambiguous fader primitive: {csg[0]}")
                    continue
                center = (low + high) / 2
            else:
                center = u
            if center:
                origin[0] += math.copysign(1.5, center)

    # B26-FADER-01 moves only the bosses and lengthens the retainers outward.
    retainer = csg[0].endswith("-RETAINER")
    bosses = [p for p in csg[2] if p[0] == 1]
    if len(bosses) != 2 or len(csg[3]) != (4 if retainer else 2):
        raise ValueError(f"Unexpected fader boss or bore count: {csg[0]}")
    for kind, origin, size in bosses + csg[3]:
        if kind != 1 or not origin[0]:
            raise ValueError(f"Unexpected fader cylinder: {csg[0]}")
        origin[0] += math.copysign(1.2, origin[0])
    if retainer:
        boxes = [p for p in csg[2] if p[0] == 0]
        if len(boxes) != 2 or any(not math.isclose(p[2][0], 5.0) for p in boxes):
            raise ValueError(f"Unexpected fader retainer: {csg[0]}")
        for _, origin, size in boxes:
            if origin[0] < 0:
                origin[0] -= 3.4
            size[0] = 8.4


def control_rows():
    """Return B24-format per-owner fixed and retainer CSG rows at B26 poses."""
    source = control_source_rows()
    targets = control_targets(source)
    result = []
    for row in source:
        owner = row["owner"]
        csg = row["CSG"]
        csg[1][0][3], csg[1][1][3] = targets[owner]
        if owner.startswith("F"):
            control_move_fader_ends(csg)
        result.append({"id": row["id"], "owner": owner, "CSG": csg})
    return result


def control_deltas():
    source = control_source_rows()
    targets = control_targets(source)
    return {r["owner"]: (targets[r["owner"]][0] - r["CSG"][1][0][3],
                         targets[r["owner"]][1] - r["CSG"][1][1][3])
            for r in source}


def control_build_retainers():
    """Return 49 retainer groups as 54 separately keyed solids."""
    result = {}
    cache = {}
    for row in control_rows():
        if "retainer" not in row["id"].lower():
            continue
        identifier, transform, additions, cuts = row["CSG"]
        key = json.dumps([additions, cuts], separators=(",", ":"))
        if key not in cache:
            cache[key] = retainer_local_retainer(row["CSG"])
        shape = cache[key]
        a, b = transform[0][:2]
        c, d = transform[1][:2]
        determinant = a * d - b * c
        if not math.isclose(abs(determinant), 1, abs_tol=1e-9):
            raise ValueError(f"Unexpected control transform: {identifier}")
        if determinant > 0:
            shape = shape.mirror(Plane.XZ)
        shape = shape.moved(Location((transform[0][3], -transform[1][3], transform[2][3]),
                                     math.degrees(math.atan2(-c, a))))
        solids = sorted(shape.solids(), key=lambda s: (s.center().X, s.center().Y, s.center().Z))
        expected = 2 if row["owner"].startswith("F") else 1
        if len(solids) != expected:
            raise ValueError(f"{identifier}: expected {expected} solids, found {len(solids)}")
        for index, solid in enumerate(solids, 1):
            name = f"{identifier}-{index}" if expected == 2 else identifier
            solid.label = f"{name} / removable control retainer / B26 review"
            result[name] = solid
    if len(result) != 54:
        raise ValueError(f"Expected 54 retainer solids, found {len(result)}")
    return result


def control_build_references():
    """Move the B24 nominal purchased-body and tip-plane references by owner."""
    delta = control_deltas()
    result = {}
    for name, shape in control_reference_build().items():
        owner = name.split("-", 1)[0]
        dx, dy = delta[owner]
        moved = shape.moved(Location((dx, -dy, 0)))
        moved.label = shape.label + " / B26 review"
        result[name] = moved
    return result


def control_build_caps(definitions=None):
    """Return legacy mesh references at the B26 poses, keyed by control owner."""
    source = control_source_rows()
    baseline = {}
    for row in source:
        transform = row["CSG"][1]
        baseline[row["owner"]] = (transform[0][3], transform[1][3])
    delta = control_deltas()
    inventory = CAP_INVENTORY
    meshes = cap_build(definitions)
    result = {}
    for row in inventory:
        if row["id"] not in meshes:
            continue
        pose = row["pose"]
        x, y = pose[3] * 10, -pose[7] * 10
        owners = [owner for owner, (bx, by) in baseline.items()
                  if math.isclose(x, bx, abs_tol=1e-6) and math.isclose(y, by, abs_tol=1e-6)]
        if len(owners) != 1:
            raise ValueError(f"Cannot uniquely associate cap with owner: {row['id']}")
        owner = owners[0]
        name = owner + "-CAP-REF"
        if name in result:
            raise ValueError(f"Duplicate cap owner: {owner}")
        dx, dy = delta[owner]
        shape = meshes[row["id"]].moved(Location((dx, -dy, 0)))
        shape.label = f"{name} / immutable legacy mesh reference / B26 review"
        result[name] = shape
    if set(result) != {owner + "-CAP-REF" for owner in baseline}:
        raise ValueError("Cap references do not cover all controls")
    return result

# b26_panels: retained constructive functions from BASELINE/models/enclosure/B26/BUILD123D03/b26_panels.py
enclosure_panel_FRONT = 96 + 5 / math.tan(math.radians(49))


enclosure_panel_AXES = {
    'R01': [(8, 8), (110, 8), (8, 132), (160, 132), (212, 132)],
    'R03': [(228, 110), (372, 110)],
    'R04': [(490, 8), (592, 8), (388, 132), (440, 132), (592, 132)],
    'R05': [(8, 148), (212, 148), (8, 230), (212, 230), (8, 312), (212, 312)],
    'R06': [(228, 148), (372, 148), (228, 312), (372, 312)],
    'R07': [(388, 148), (592, 148), (388, 230), (592, 230), (388, 312), (592, 312)],
}


def enclosure_panel_owner(x, y):
    if x < 220:
        rear = y < (165 if 75 <= x <= 145 else 140)
        return 'R01' if rear else 'R05'
    if x < 380:
        return 'R03' if y < 140 else 'R06'
    rear = y < (165 if 455 <= x <= 525 else 140)
    return 'R04' if rear else 'R07'


def enclosure_panel_exterior(x, y):
    y = -y
    t = 1e-5
    if ((abs(x) < t or abs(x-600) < t) and 3-t <= y <= 317+t or
            (abs(y) < t or abs(y-320) < t) and 3-t <= x <= 597+t):
        return True
    return any((x-cx)*(1 if cx == 3 else -1) <= t and
               (y-cy)*(1 if cy == 3 else -1) <= t and
               abs(math.hypot(x-cx, y-cy)-3) < t
               for cx, cy in ((3, 3), (597, 3), (3, 317), (597, 317)))


def enclosure_panel_outer_rounds(part, identifier):
    corners = {'R01': (0, 0), 'R04': (600, 0),
               'R05': (0, -320), 'R07': (600, -320)}
    if identifier in corners:
        x, y = corners[identifier]
        edges = [e for e in part.edges() if e.length > 1 and
                 all(abs(p.X-x) < 1e-6 and abs(p.Y-y) < 1e-6 for p in panel_edge_points(e))]
        if len(edges) != 1:
            raise ValueError((identifier, 'corner edges', len(edges)))
        part = fillet(edges, 3)
    edges = panel_top_edges(part, enclosure_panel_exterior)
    if edges:
        part = fillet(edges, .8)
    return part


def enclosure_panel_panel(identifier, data, b19, proof, moves):
    if identifier == 'R03':
        part = panel_box(220, 380, -140, -enclosure_panel_FRONT, 18, 20)
    elif identifier == 'R06':
        part = panel_box(220, 380, -320, -140, 18, 20)
    else:
        left = identifier in ('R01', 'R05')
        rear = identifier in ('R01', 'R04')
        x0, x1 = (0, 220) if left else (380, 600)
        a, b = (75, 145) if left else (455, 525)
        if rear:
            part = panel_box(x0, x1, -140, 0, 18, 20)
            part += panel_box(a, b, -165, -140, 18, 20)
            cut0, cut1 = (153.55, 220) if left else (380, 446.45)
            part -= panel_box(cut0, cut1, -enclosure_panel_FRONT, 0, 17, 21)
        else:
            part = panel_box(x0, x1, -320, -140, 18, 20)
            part -= panel_box(a, b, -165, -140, 17, 21)

    rows = []
    for original in data['b15_panel_apertures']:
        row = list(original)
        name = row[0]
        if not (name.startswith(('B', 'T', 'P', 'F', 'L')) or name == 'E01'):
            continue
        if name in moves and name not in ('E01', 'T01', 'T02'):
            row[1:3] = moves[name]
        row[2] += 20
        if name in ('E01', 'T01', 'T02'):
            row[2] = 125
        if name in ('B23', 'B24'):
            row[2] = 255
        if enclosure_panel_owner(row[1], row[2]) == identifier:
            rows.append(row)
            part -= panel_profile(row)
    part = enclosure_panel_outer_rounds(part, identifier)

    wells = [r for r in b19['fader_recesses']['instances'] if r['panel'] == identifier]
    for r in wells:
        x, y = r['table_xy']
        w, h = (69.7, 14) if r['id'] == 'F05' else (14, 69.7)
        part -= Pos(x, -(y+20), 19) * extrude(RectangleRounded(w, h, 3), amount=3)
    if wells:
        def on_well(x, y):
            for r in wells:
                cx, cy = r['table_xy']
                w, h = (69.7, 14) if r['id'] == 'F05' else (14, 69.7)
                qx, qy = abs(x-cx)-(w/2-3), abs(y+cy+20)-(h/2-3)
                if abs(math.hypot(max(qx, 0), max(qy, 0))+min(max(qx, qy), 0)-3) < 1e-5:
                    return True
            return False
        part = panel_chamfer_edges(part, on_well)

    jog = {'R01': 110, 'R05': 110, 'R04': 490, 'R07': 490}.get(identifier)
    if jog is not None:
        part -= panel_cylinder(jog, -165, 17, 26, 5)
        part -= panel_cylinder(jog, -165, 19, 54, 3)
        part = panel_chamfer_edges(part, lambda x, y: abs(math.hypot(x-jog, y+165)-54) < 1e-5)
    caps = [r for r in rows if r[0].startswith(('B', 'T'))]
    if caps:
        part = panel_chamfer_edges(part, lambda x, y: any(panel_cap_edge(r, x, y) for r in caps))

    for mark in proof['P_marks']:
        name = mark['id'].split('-')[0]
        if name in ('P01', 'P02', 'P03'):
            continue
        points = mark['polygon_XY']
        cx = sum(p[0] for p in points)/4
        cy = sum(p[1] for p in points)/4 + 20
        if enclosure_panel_owner(cx, cy) == identifier:
            part += panel_polygon([(x, -y-20) for x, y in points], 20, .4)
    if identifier == 'R04':
        patterns = [r['polygon_XY'] for r in proof['P_marks'] if r['id'] == 'P04']
        for target_y in (41, 69, 97):
            for points in patterns:
                part += panel_polygon([(x-244+559, -(y-131+target_y)) for x, y in points], 20, .4)
    for name, x, y, *_ in data['b15_fader_poses']:
        y += 20
        if enclosure_panel_owner(x, y) != identifier:
            continue
        travel = 28 if name == 'F05' else 41
        for j in range(11):
            u = -travel/2 + j*travel/10
            length = 4 if j in (0, 5, 10) else 2
            for sign in (-1, 1):
                points = [(uu, sign*vv) for uu, vv in
                          ((u-.4, 2.4), (u+.4, 2.4), (u+.4, 2.4+length), (u-.4, 2.4+length))]
                points = [(x+uu, -(y-vv)) if name == 'F05' else (x+vv, -(y+uu))
                          for uu, vv in points]
                part += panel_polygon(points, 19, .4)
    for x, y in enclosure_panel_AXES[identifier]:
        part -= panel_cylinder(x, -y, 17, 1.7, 5)
        part -= Pos(x, -y, 18.7) * Cone(1.7, 3, 1.3, align=panel_CMIN)
    return part


def enclosure_panel_roof(identifier):
    left = identifier == 'D02L'
    x0, x1 = (153.55, 335) if left else (335, 446.45)
    a = math.radians(49)
    c, s = math.cos(a), math.sin(a)
    cy, h, j, u = 96-40*c, 23+40*s, 96-80*c, 25+80*s
    part = panel_section(x0, x1-x0, [(0, u-2), (-j, u-2), (-enclosure_panel_FRONT, 18),
                                (-enclosure_panel_FRONT, 20), (-j, u), (0, u)])
    part += panel_section(153.55 if left else 444.45, 2,
                    [(-2, 18), (-enclosure_panel_FRONT, 18), (-enclosure_panel_FRONT, 20), (-j, u), (-2, u)])

    def place(shape, side, row):
        if side*row > 0:
            shape = shape.mirror(Plane.XZ)
        frame = Plane(origin=(300, -cy, h), x_dir=(side, 0, 0), z_dir=(0, -s, c))
        return shape.moved(frame.location)

    part -= place(panel_box(-136, 136, -36, 36, -5, 5), 1, 1)
    for x in (210, 230, 300, 370, 390):
        if x0 < x < x1:
            part -= panel_cylinder(x, -4, u-2.01, 1.7, 2.02)
            part -= Pos(x, -4, u-1.3) * Cone(1.7, 3, 1.3, align=panel_CMIN)
    if left:
        part += panel_box(325, 345, -29, -13, u-10, u-2)
        for y in (18, 24):
            part -= panel_cylinder(340, -y, u-9, 1.25, 7.01)
    else:
        for y in (18, 24):
            part -= panel_cylinder(340, -y, u-2.01, 1.7, 2.02)
            part -= Pos(340, -y, u-1.3) * Cone(1.7, 3, 1.3, align=panel_CMIN)
    x = 228 if left else 372
    part += panel_section(x-5, 10, [(-95, 16), (-116, 16), (-116, 18),
                              (-enclosure_panel_FRONT, 18), (-95, 23+math.tan(a))])
    part -= panel_cylinder(x, -110, 15.99, 1.7, 2.02)
    for row in (-1, 1):
        support = panel_box(138.5, 144.2, 18, 30, -21.2, 0)
        support += panel_box(138.25, 140, 20, 39.797470349551496, -21, -.25)
        support += panel_box(130, 140, 38.297470349551496, 39.797470349551496, -21, -.25)
        support -= panel_box(136, 146, 19.9, 28.1, -21.2, -18)
        support -= panel_cylinder(140.7, 24, -18.1, 1.25, 7.1)
        support -= panel_cylinder(140.7, 24, -60, 4, 39)
        part += place(support, -1 if left else 1, row)
    edges = panel_top_edges(part, enclosure_panel_exterior, u)
    return fillet(edges, .8) if edges else part


def enclosure_panel_build():
    data, _, b19, proof, moves = panel_load_data()
    parts = {'PANEL_'+i: enclosure_panel_panel(i, data, b19, proof, moves) for i in enclosure_panel_AXES}
    parts.update({i: enclosure_panel_roof(i) for i in ('D02L', 'D02R')})
    for key, part in parts.items():
        part.label = key + ' B26-INTEGRATED-01 review'
    return parts

# b26_equipment: retained constructive functions from BASELINE/models/enclosure/B26/BUILD123D03/b26_equipment.py
def equipment_build():
    old = equipment_reference_build()
    result = {}
    for name in ("PI-envelope", "DAC-envelope", "PSU-envelope", "J01-body", "J01-nut"):
        result[name] = Pos(0, -20, 0) * old[name]
    result["D01-front-plane"] = Pos(0, 0, 5) * old["D01-front-plane"]
    result["RCA-front-plane"] = old["RCA-front-plane"]
    boards = EQUIPMENT_BOARDS
    if {row["id"] for row in boards} != {"U1", "U2", "U3", "U4"}:
        raise ValueError("Unexpected B25 board set")
    for row in boards:
        x, y = row["centre_XY"]
        y += 20
        width, depth = row["plan_size_XY"]
        z0, z1 = row["reference_Z"]
        name = row["id"] + "-envelope"
        result[name] = table_box(x-width/2, x+width/2, y-depth/2, y+depth/2, z0, z1)
    for name, shape in result.items():
        shape.label = name + " incomplete purchased reference, not vendor geometry"
    return result

# b26_fasteners: retained constructive functions from BASELINE/models/enclosure/B26/BUILD123D03/b26_fasteners.py
def enclosure_fastener_build():
    """Return stable IDs mapped to installed, incomplete reference solids."""
    result = {}
    joint = fastener_socket_screw(1.5, 8, 2.75, 3)
    closure = fastener_countersunk(1.5, 8, 3)
    control_m2 = fastener_countersunk(1, 6, 2.2)
    control_m16 = fastener_countersunk(.8, 5, 1.6)

    def add(identifier, shape):
        if identifier in result:
            raise ValueError(f"Duplicate fastener ID: {identifier}")
        shape.label = f"{identifier} / purchased nominal reference / incomplete"
        result[identifier] = shape

    for identifier, normal, x, y in enclosure_joints():
        for side in (-1, 1):
            px = x + 9 * side if normal == 'X' else x
            py = y + 9 * side if normal == 'Y' else y
            add(f"C07-{identifier}-{'A' if side < 0 else 'B'}-M3x8",
                Pos(px, -py, 11) * joint)

    panels = {
        'R01': ((8, 8), (110, 8), (8, 132), (160, 132), (212, 132)),
        'R03': ((228, 110), (372, 110)),
        'R04': ((490, 8), (592, 8), (388, 132), (440, 132), (592, 132)),
        'R05': ((8, 148), (212, 148), (8, 230), (212, 230), (8, 312), (212, 312)),
        'R06': ((228, 148), (372, 148), (228, 312), (372, 312)),
        'R07': ((388, 148), (592, 148), (388, 230), (592, 230), (388, 312), (592, 312)),
    }
    for panel, axes in panels.items():
        for index, (x, y) in enumerate(axes, 1):
            add(f"{panel}-closure-{index}-BN616-M3x8", Pos(x, -y, 20) * closure)
    for index, x in enumerate((210, 230, 300, 370, 390), 1):
        add(f"roof-rear-{index}-BN616-M3x8", Pos(x, -4, enclosure_REAR_TOP + 2) * closure)
    for index, y in enumerate((18, 24), 1):
        add(f"roof-lap-{index}-BN616-M3x8", Pos(340, -y, enclosure_REAR_TOP + 2) * closure)
    for index, x in enumerate((361.5, 416.5), 1):
        frame = Plane(origin=(x, -54.35, 0), x_dir=(1, 0, 0), z_dir=(0, 0, -1))
        add(f"PSU-{index}-BN616-M3x6", fastener_countersunk(1.5, 6, 3).moved(frame.location))


    for row in control_rows():
        if 'retainer' not in row['id'].lower():
            continue
        owner = row['owner']
        _, transform, _, cuts = row['CSG']
        screw = control_m16 if owner.startswith('P') else control_m2
        head_radius = 1.6 if owner.startswith('P') else 2.2
        number = 0
        for kind, origin, size in cuts:
            if kind != 1 or abs(size[1] - head_radius) > 1e-7 or size[0] == size[1]:
                continue
            u, v, w = origin
            x = transform[0][0] * u + transform[0][1] * v + transform[0][3]
            y = transform[1][0] * u + transform[1][1] * v + transform[1][3]
            z = transform[2][3] + w + size[2]
            number += 1
            add(f"{owner}-retainer-{number}-{'M1.6x5' if owner.startswith('P') else 'M2x6'}",
                Pos(x, -y, z) * screw)
        expected = 4 if owner.startswith('P') else 2
        if number != expected:
            raise ValueError(f"{owner}: expected {expected} retainer screw axes, found {number}")

    # B10 specifies ISO4762 under the B22 toe, with the shaft pointing inward.
    shaft = joint.moved(Plane(origin=(140.7, 24, -21), x_dir=(1, 0, 0),
                              z_dir=(0, 0, -1)).location)
    angle = radians(49)
    c, s = cos(angle), sin(angle)
    cy, height = 96 - 40*c, 23 + 40*s
    for side, row in product((-1, 1), repeat=2):
        local = shaft.mirror(Plane.XZ) if side * row > 0 else shaft
        frame = Plane(origin=(300, -cy, height), x_dir=(side, 0, 0), z_dir=(0, -s, c))
        add(f"display-toe-{side}-{row}-ISO4762-M3x8", local.moved(frame.location))

    if len(result) != 197:
        raise ValueError(f"Expected 197 enclosure fastener references, found {len(result)}")
    return result

# lap_spec: retained constructive functions from model/lap_spec.py
STATIONS = (
    ("S01", 220.0, 22.0, "X"), ("S02", 220.0, 96.0, "X"),
    ("S03", 380.0, 22.0, "X"), ("S04", 380.0, 92.0, "X"),
    ("S05", 220.0, 178.0, "X"), ("S06", 220.0, 256.0, "X"),
    ("S07", 380.0, 178.0, "X"), ("S08", 380.0, 256.0, "X"),
    ("S09", 60.0, 140.0, "Y"), ("S10", 150.0, 140.0, "Y"),
    ("S11", 185.0, 140.0, "Y"), ("S12", 260.0, 140.0, "Y"),
    ("S13", 340.0, 140.0, "Y"), ("S14", 415.0, 140.0, "Y"),
    ("S15", 450.0, 140.0, "Y"), ("S16", 540.0, 140.0, "Y"),
)


REMOVED_CLAMPS = ("S11", "S14")


CLAMP_STATIONS = tuple(s for s in STATIONS if s[0] not in REMOVED_CLAMPS)


CORNER_FEET = (
    ("F01", 16.0, 16.0, "X"), ("F02", 584.0, 16.0, "X"),
    ("F03", 16.0, 304.0, "X"), ("F04", 584.0, 304.0, "X"),
)


FOOT_STATIONS = (*CLAMP_STATIONS, *CORNER_FEET)


def bridge_shift(station_id):
    if station_id in ("S05", "S06"):
        return -2.0
    if station_id in ("S07", "S08"):
        return 2.0
    return 0.0

# static_jog: retained constructive functions from model/static_jog.py
def jog_cyl(r, z0, z1, x=0, y=0):
    return Solid.make_cylinder(r, z1 - z0, plane=Plane(origin=(x, y, z0)))


def jog_box(x0, x1, y0, y1, z0, z1):
    return Solid.make_box(x1 - x0, y1 - y0, z1 - z0, plane=Plane(origin=(x0, y0, z0)))


def jog_cone(r0, r1, z0, z1, x=0, y=0):
    return Solid.make_cone(r0, r1, z1 - z0, plane=Plane(origin=(x, y, z0)))


def jog_xy(r, a):
    return r * math.cos(math.radians(a)), r * math.sin(math.radians(a))


def jog_radial_box(a, u0, u1, v0, v1, z0, z1):
    return jog_box(u0, u1, v0, v1, z0, z1).rotate(Axis.Z, a)


def jog_hex(af, z0, z1, x, y):
    radius = af / math.sqrt(3)
    points = [(x + radius * math.cos(math.radians(30 + 60 * i)),
               y + radius * math.sin(math.radians(30 + 60 * i)), z0) for i in range(6)]
    return Solid.extrude(Face(Wire.make_polygon(points)), (0, 0, z1 - z0))


def jog_groove_profile(z, offset):
    outer, inner = 19.2 + offset, 16.8 - offset
    xc = 2.8
    yo = math.sqrt(18.4 ** 2 - xc ** 2)
    yi = math.sqrt(17.6 ** 2 - xc ** 2)
    ol, or_ = (-xc, yo), (xc, yo)
    il, ir = (-xc, yi), (xc, yi)

    def radial(point, radius):
        factor = radius / math.hypot(*point)
        return tuple(v * factor for v in point)

    outer_left, outer_right = radial(ol, outer), radial(or_, outer)
    inner_left, inner_right = radial(il, inner), radial(ir, inner)
    left_low, left_up = (-2 + offset, yi), (-2 + offset, yo)
    right_up, right_low = (2 - offset, yo), (2 - offset, yi)

    def arc(center, start, end, ccw=True):
        a = math.degrees(math.atan2(start[1] - center[1], start[0] - center[0]))
        b = math.degrees(math.atan2(end[1] - center[1], end[0] - center[0]))
        sweep = (b - a) % 360 if ccw else -((a - b) % 360)
        return CenterArc(center, math.dist(center, start), a, sweep)

    edges = [
        arc((0, 0), outer_left, outer_right),
        arc(or_, outer_right, right_up),
        Line(right_up, right_low),
        arc(ir, right_low, inner_right),
        arc((0, 0), inner_right, inner_left, False),
        arc(il, inner_left, left_low),
        Line(left_low, left_up),
        arc(ol, left_up, outer_left),
    ]
    return Pos(0, 0, z) * make_face(edges)


def jog_platter_exterior():
    # This is only the defined exterior portion, not the complete P01 rotor.
    groove = loft([jog_groove_profile(35.6, 0), jog_groove_profile(36.4, .8)], ruled=True)
    with BuildPart() as p:
        insert(jog_cone(55, 52.5, 21.4, 36.4))
        tool = Solid.make_cylinder(5, 9.75, plane=Plane(origin=(50.25, 0, 28.9), z_dir=(1, 0, 0)))
        start_edges = [e for e in tool.edges() if abs(e.center().X - 50.25) < 1e-7]
        tool = tool.fillet(1, start_edges)
        for a in range(0, 360, 30):
            insert(tool.rotate(Axis.Z, a), mode=Mode.SUBTRACT)
        insert(groove, mode=Mode.SUBTRACT)
    return p.part


def jog_thread_ridge(radial_offset):
    root = 14.725 + radial_offset
    crest = 14.975 + radial_offset
    half_root = .03125 + .25 / math.sqrt(3)
    z = 2.5
    # Ruled helical faces avoid the invalid Boolean topology of a radial pipe sweep.
    profile = [(root - .025, -half_root), (root, -half_root),
               (crest, -.03125), (crest, .03125),
               (root, half_root), (root - .025, half_root)]
    helices = [Edge.make_helix(.5, 3.5, r, center=(0, 0, z + dz))
               for r, dz in profile]
    faces = [Face.make_surface_from_curves(a, b)
             for a, b in zip(helices, helices[1:] + helices[:1])]
    for dz in (0, 3.5):
        faces.append(Face(Wire.make_polygon([(r, 0, z + offset + dz)
                                             for r, offset in profile])))
    shell = Shell(faces, tolerance=1e-5)
    if not shell.is_valid or not shell.is_manifold:
        raise ValueError("F13 helical ridge shell is not valid and closed")
    return Solid(shell) & jog_cyl(16, 3, 5.5)


def jog_rotor():
    platter = jog_platter_exterior()
    with BuildPart() as shaft:
        insert(jog_cyl(14.725, 3, 5.5))
        insert(jog_thread_ridge(0))
        insert(jog_cyl(14.975, 5.5, 21.4))
        insert(jog_cyl(16.1, 19.5, 21.4))
        insert(jog_cyl(13, 3, 21.4), mode=Mode.SUBTRACT)
    root_edges = [
        e for e in shaft.part.edges()
        if abs(e.center().Z - 19.5) < 1e-6
        and abs(e.length - 2 * math.pi * 14.975) < 1e-5
    ]
    if len(root_edges) != 1:
        raise ValueError("Cannot identify the P01 shoulder root edge")
    shaft_body = shaft.part.fillet(.2, root_edges)
    if not shaft_body.is_inside((-14.97, 0, 4.25)):
        raise RuntimeError("F13 P01 T30 Boolean lost the thread crest; full model is blocked")
    with BuildPart() as p:
        insert(shaft_body)
        insert(jog_cyl(6, 6.6, 21.4))
        insert(platter)
        insert(jog_cyl(4.1, 6.6, 10.8), mode=Mode.SUBTRACT)
    return p.part


def jog_collar(z0, z1):
    with BuildPart() as p:
        insert(jog_cyl(16.1, z0, z1))
        insert(jog_cyl(14.775, z0, z1), mode=Mode.SUBTRACT)
        insert(jog_thread_ridge(.05), mode=Mode.SUBTRACT)
        for a in (0, 120, 240):
            insert(jog_radial_box(a, 15.6, 16.2, -1, 1, z0, z1), mode=Mode.SUBTRACT)
    if p.part.is_inside((-15.0, 0, z0 + .25)):
        raise RuntimeError("F13 collar T30 Boolean lost the thread groove; full model is blocked")
    return p.part


def jog_carrier():
    with BuildPart() as p:
        insert(jog_cyl(23, 5.5, 19.5))
        for a in (0, 120, 240):
            x, y = jog_xy(23, a)
            insert(jog_cyl(2.5, 5.5, 9.5, x, y))
            insert(jog_cyl(2.5, 15.5, 19.5, x, y))
        for a in (90, 210, 330):
            x, y = jog_xy(31, a)
            insert(jog_cyl(5, 6, 9, x, y))
            insert(jog_radial_box(a, 22, 31, -5, 5, 6, 9))
        insert(jog_cyl(21.075, 5.5, 19.5), mode=Mode.SUBTRACT)
        for a in (0, 120, 240):
            x, y = jog_xy(23, a)
            insert(jog_cyl(.8, 5.5, 8.5, x, y), mode=Mode.SUBTRACT)
            insert(jog_cyl(.8, 16.5, 19.5, x, y), mode=Mode.SUBTRACT)
        for a in (90, 210, 330):
            x, y = jog_xy(31, a)
            insert(jog_cyl(1, 6, 9, x, y), mode=Mode.SUBTRACT)
    return p.part


def jog_cover(upper):
    z0, z1 = (19.5, 21) if upper else (4, 5.5)
    with BuildPart() as p:
        insert(jog_cyl(23, z0, z1))
        for a in (0, 120, 240):
            x, y = jog_xy(23, a)
            insert(jog_cyl(2.5, z0, z1, x, y))
        insert(jog_cyl(20, z0, z1), mode=Mode.SUBTRACT)
        for a in (0, 120, 240):
            x, y = jog_xy(23, a)
            insert(jog_cyl(1.2, z0, z1, x, y), mode=Mode.SUBTRACT)
            if upper:
                insert(jog_cone(1.2, 2.1, z1 - .9, z1, x, y), mode=Mode.SUBTRACT)
            else:
                insert(jog_cone(2.1, 1.2, z0, z0 + .9, x, y), mode=Mode.SUBTRACT)
    return p.part


def jog_sensor_seat():
    """Build the inherited nominal PCB support for integral shell attachment."""
    with BuildPart() as p:
        insert(jog_cyl(25, 0, 1))
        for sign in (-1, 1):
            insert(jog_cyl(.9, 1, 2.5, sign * 6, 0))
            insert(jog_box(7.6 if sign > 0 else -12.4, 12.4 if sign > 0 else -7.6, -3, 3, 1, 3))
        insert(jog_box(-5, 5, -26, -3, 0, 1), mode=Mode.SUBTRACT)
        for sign in (-1, 1):
            x = sign * 10
            insert(jog_hex(4.1, .6, 2.3, x, 0), mode=Mode.SUBTRACT)
            insert(jog_box(x - 2.1, x + 2.1, 0, 8, .6, 2.3), mode=Mode.SUBTRACT)
            insert(jog_cyl(1.1, .2, 3, x, 0), mode=Mode.SUBTRACT)
    return p.part


def jog_toe():
    with BuildPart() as p:
        insert(jog_box(6.8, 12.4, -2.5, 2.5, 3, 4.3))
        insert(jog_cyl(1.1, 3, 4.3, 10, 0), mode=Mode.SUBTRACT)
        insert(jog_cone(1.1, 1.3, 4.1, 4.3, 10, 0), mode=Mode.SUBTRACT)
    return p.part


def jog_board():
    with BuildPart() as p:
        insert(jog_cyl(9, 1, 3))
        insert(jog_box(-7.5, 7.5, -8.5, 8.5, 1, 3), mode=Mode.INTERSECT)
        for x in (-6, 6):
            insert(jog_cyl(1.1, 1, 3, x, 0), mode=Mode.SUBTRACT)
    return p.part


def jog_bearing(z):
    return jog_cyl(21, z, z + 7) - jog_cyl(15, z, z + 7)


def jog_build():
    """Build jog and floor-fixed sensor occurrences at their retained placements."""
    printed = {
        "P01 platter and threaded rotor": jog_rotor(),
        "P02 carrier B26-JOG-01": jog_carrier(),
        "P06 lower cover": jog_cover(False),
        "P05 upper cover": jog_cover(True),
        "P08 toe right": jog_toe(),
        "P08 toe left": jog_toe().rotate(Axis.Z, 180),
        "P04 threaded retaining collar": jog_collar(4, 5.5),
        "P07 threaded jam collar": jog_collar(3, 4),
    }
    reference = {
        "SKF 61806-2RS1 lower simplified envelope": jog_bearing(5.5),
        "SKF 61806-2RS1 upper simplified envelope": jog_bearing(12.5),
        "D8x4 diametric magnet nominal envelope": jog_cyl(4, 6.6, 10.6),
        "AS5048A PCB nominal contour laminate only no components": jog_board(),
    }
    for sign in (-1, 1):
        x = sign * 10
        reference[f"PCB M2 nut nominal threadless {sign}"] = jog_hex(4, .65, 2.25, x, 0) - jog_cyl(1, .65, 2.25, x, 0)
        reference[f"PCB M2x4 cap screw nominal threadless {sign}"] = jog_cyl(1, .3, 4.3, x, 0) + jog_cyl(1.9, 4.3, 6.3, x, 0)
    for i, a in enumerate((90, 210, 330), 1):
        x, y = jog_xy(31, a)
        reference[f"floor M2.5x8 ETTINGER nominal threadless {i}"] = jog_cyl(1.25, .5, 8.5, x, y) + jog_cyl(2.25, -2, .5, x, y)
    for i, a in enumerate((0, 120, 240), 1):
        x, y = jog_xy(23, a)
        reference[f"upper M2x4 DIN7991 nominal threadless {i}"] = jog_cyl(1, 17, 20, x, y) + jog_cone(1, 2, 20, 21, x, y)
        reference[f"lower M2x4 DIN7991 nominal threadless {i}"] = jog_cyl(1, 5, 8, x, y) + jog_cone(2, 1, 4, 5, x, y)
    result = {"printed": {}, "reference": {}}
    for side, x in (("left", 110), ("right", 490)):
        for category, parts in (("printed", printed), ("reference", reference)):
            for name, part in parts.items():
                shape = part.rotate(Axis.Z, 60).moved(Location((x, -165, 2)))
                key = f"{side} {name}"
                shape.label = key
                result[category][key] = shape
    return result

# lap_hardware: retained constructive functions from model/lap_hardware.py
lap_CMIN = (Align.CENTER, Align.CENTER, Align.MIN)


def lap_cylinder(radius, height, z):
    return Pos(0, 0, z) * Cylinder(radius, height, align=lap_CMIN)


def lap_offset(normal, u, v=0):
    """Map table seam-normal/perpendicular offsets to CAD XY."""
    if normal == "X":
        return u, -v
    if normal == "Y":
        return v, -u
    raise ValueError(f"Unknown station normal: {normal!r}")


def lap_placed(shape, x, y, label):
    result = Pos(x, -y, 0) * shape
    result.label = label
    return result


def lap_build_bridges():
    """Return printed bridge occurrences keyed by station ID."""
    result = {}
    for station, x, y, normal in CLAMP_STATIONS:
        dx, dy = lap_offset(normal, bridge_shift(station))
        width, depth = (32, 10) if normal == "X" else (10, 32)
        part = Pos(dx, dy, 2) * Box(width, depth, 3, align=lap_CMIN)
        for u in (-5, 5):
            hx, hy = lap_offset(normal, u)
            part -= Pos(hx, hy, 0) * lap_cylinder(1.45, 3, 2)
        kind = "B" if bridge_shift(station) else "A"
        result[station] = lap_placed(part, x, y, f"{station} / bridge {kind} / printed PETG candidate")
    assert len(result) == 14
    return result


def lap_build_feet():
    """Return printed FT03 occurrences seated directly against the flat floor."""
    result = {}
    for station, x, y, normal in FOOT_STATIONS:
        part = lap_cylinder(10, 6, -8) - lap_cylinder(7, 1, -8)
        for u in (-5, 5):
            px, py = lap_offset(normal, u)
            part -= Pos(px, py, 0) * lap_cylinder(3.5, 3.6, -5.6)
        for u in (-3, 3):
            for v in (-6.5, 6.5):
                px, py = lap_offset(normal, u, v)
                part += Pos(px, py, -2) * Cone(1.7, 1.5, 1.2, align=lap_CMIN)
        result[station] = lap_placed(part, x, y, f"{station} / FT03 / printed PETG candidate")
    assert len(result) == 18
    return result


def lap_build_joint_hardware():
    """Return individually identified incomplete purchased reference solids.

    Screw shanks are smooth and heads have no drive. Nuts omit threads; the
    SJ5012 cylinder is a typical envelope, not the purchased pad's exact shape.
    """
    screw = lap_cylinder(1.25, 12, -2.55) + lap_cylinder(2.25, 2.5, -5.05)
    washer = lap_cylinder(3, .55, -2.55) - lap_cylinder(1.35, .55, -2.55)
    nut = Pos(0, 0, 5) * extrude(RegularPolygon(2.5, 6, major_radius=False), amount=2)
    nut -= lap_cylinder(1.25, 2, 5)
    pad = lap_cylinder(6.35, 3.5, -10.5)
    result = {}
    for station, x, y, normal in CLAMP_STATIONS:
        for side, u in (("minus", -5), ("plus", 5)):
            dx, dy = lap_offset(normal, u)
            for name, shape, description in (
                ("screw", screw, "ISO4762 M2.5x12 / smooth shank, no drive"),
                ("washer", washer, "ISO7089 M2.5 nominal washer"),
                ("nut", nut, "ISO4032 M2.5 nominal hex nut / no threads"),
            ):
                identifier = f"{station}-{side}-{name}"
                part = Pos(x + dx, -y + dy, 0) * shape
                part.label = f"{identifier} / purchased incomplete reference / {description}"
                result[identifier] = part
    for station, x, y, _ in FOOT_STATIONS:
        identifier = f"{station}-SJ5012"
        result[identifier] = lap_placed(
            pad, x, y, f"{identifier} / purchased incomplete reference / typical cylindrical envelope"
        )
    assert len(result) == 102
    return result

# lap_shell: retained constructive functions from model/lap_shell.py
lower_KEYS = tuple(f'C{i:02}' for i in range(1, 7))


lower_REAR = {'S1-M3-POST', 'S2a-M1-POST', 'S2a-M3-POST', 'S3-M1-POST'}


lower_MASKED_CONTROLS = ('T01-FIXED', 'T02-FIXED', 'T03-FIXED', 'T06-FIXED',
                    'P04-FIXED', 'P09-FIXED', 'E01-fixed_cage')


lower_Z0, lower_Z1 = -10, 100


def lower_empty(shape):
    return shape is None or shape.is_empty


def lower_add(a, b):
    if lower_empty(a):
        return b
    if lower_empty(b):
        return a
    return a + b


def lower_sub(a, b):
    return a if lower_empty(a) or lower_empty(b) else a - b


def lower_and(a, b):
    if lower_empty(a) or lower_empty(b):
        return None
    c = a & b
    return None if lower_empty(c) or c.volume < 1e-9 else c


def lower_union(shapes):
    result = None
    for shape in shapes:
        result = lower_add(result, shape)
    return result


def lower_rect(x0, x1, y0, y1):
    return table_box(x0, x1, y0, y1, lower_Z0, lower_Z1)


def lower_circle(x, y, radius):
    return table_cyl(x, y, lower_Z0, lower_Z1, radius)


def lower_owner(x, y, upper=False):
    a, b, c = (208, 368, 128) if upper else (232, 392, 152)
    return lower_KEYS[(0 if y < c else 3) + (0 if x < a else 1 if x < b else 2)]


def lower_domains(upper=False):
    xs = (0, 208, 368, 600) if upper else (0, 232, 392, 600)
    ys = (0, 128, 320) if upper else (0, 152, 320)
    return {lower_KEYS[row * 3 + col]: lower_rect(xs[col], xs[col+1], ys[row], ys[row+1])
            for row in range(2) for col in range(3)}


def lower_transfer(domains, mask, owner):
    for key in lower_KEYS:
        domains[key] = lower_sub(domains[key], mask)
    domains[owner] = lower_add(domains[owner], mask)


def lower_control_bounds(control):
    _, matrix, additions, _ = control['CSG']
    if [row[:3] for row in matrix[:3]] != [[1, 0, 0], [0, 1, 0], [0, 0, 1]]:
        raise ValueError('Unexpected mask transform: ' + control['id'])
    x0 = y0 = math.inf
    x1 = y1 = -math.inf
    for kind, point, size in additions:
        if kind not in (0, 1):
            raise ValueError('Unexpected mask primitive: ' + control['id'])
        x, y = matrix[0][3] + point[0], matrix[1][3] + point[1]
        radius = max(size[:2]) if kind == 1 else 0
        x0, x1 = min(x0, x-radius), max(x1, x + (size[0] if kind == 0 else radius))
        y0, y1 = min(y0, y-radius), max(y1, y + (size[1] if kind == 0 else radius))
    if not math.isfinite(x0):
        raise ValueError('Empty control mask: ' + control['id'])
    return x0, x1, y0, y1


def lower_plan(data):
    """Translate the approved screen predicate into closed extruded plan sets."""
    lower = lower_domains()
    nominal_upper = lower_domains(True)
    perimeter = lower_union((lower_rect(0, 1, 0, 320), lower_rect(599, 600, 0, 320),
                        lower_rect(0, 600, 0, 1), lower_rect(0, 600, 319, 320)))
    top0 = {k: lower_add(lower_sub(nominal_upper[k], perimeter), lower_and(lower[k], perimeter)) for k in lower_KEYS}
    upper = dict(top0)
    rear_masks, masks, rings = [], [], []
    posts = []
    for post in data['schedules']['posts']:
        x, y = post['centre_XY']
        r = post['foot']['bottom_radius']
        intersects = any(x-r < b and x+r > a and y-r < d and y+r > c
                         for a, b, c, d in ((208, 232, 0, 320), (368, 392, 0, 320), (0, 600, 128, 152)))
        if intersects:
            if r != 4.5:
                raise ValueError('Unexpected post radius: ' + post['id'])
            rear = post['id'] in lower_REAR
            owner = lower_owner(x, y, not rear)
            disk = lower_and(lower_circle(x, y, r), lower_rect(0, 600, 0, 320))
            ring = lower_sub(lower_circle(x, y, r + .2), disk)
            rings.append(lower_and(ring, lower_union(top0[k] for k in lower_KEYS if k != owner)))
            masks.append(disk)
            lower_transfer(upper, disk, owner)
            if rear:
                rear_masks.append(disk)
                lower_transfer(lower, disk, owner)
            posts.append(post['id'])
    if len(posts) != 24 or len(rear_masks) != 4:
        raise ValueError('Unexpected affected post set')
    controls = {c['id']: c for c in data['schedules']['controls']}
    control_owners = {}
    for identifier in lower_MASKED_CONTROLS:
        control = controls[identifier]
        x0, x1, y0, y1 = lower_control_bounds(control)
        matrix = control['CSG'][1]
        owner = lower_owner(matrix[0][3], matrix[1][3], True)
        mask = lower_rect(x0, x1, y0, y1)
        ring = lower_sub(lower_rect(x0-.2, x1+.2, y0-.2, y1+.2), mask)
        rings.append(lower_and(ring, lower_union(top0[k] for k in lower_KEYS if k != owner)))
        masks.append(mask)
        lower_transfer(upper, mask, owner)
        control_owners[identifier] = owner
    expected = {'T01-FIXED': 'C02', 'T02-FIXED': 'C02', 'E01-fixed_cage': 'C02',
                'T03-FIXED': 'C05', 'T06-FIXED': 'C05', 'P04-FIXED': 'C05', 'P09-FIXED': 'C05'}
    if control_owners != expected:
        raise ValueError('Unexpected control ownership')
    lx = lower_union((lower_rect(231.8, 232, 0, 320), lower_rect(391.8, 392, 0, 320)))
    ly = lower_rect(0, 600, 151.8, 152)
    ux = lower_union((lower_rect(208, 208.2, 0, 320), lower_rect(368, 368.2, 0, 320)))
    uy = lower_rect(0, 600, 128, 128.2)
    outer_x = lower_union((lower_rect(0, 1, 0, 320), lower_rect(599, 600, 0, 320)))
    outer_y = lower_union((lower_rect(0, 600, 0, 1), lower_rect(0, 600, 319, 320)))
    hx = lower_add(lower_sub(ux, outer_y), lower_and(lx, outer_y))
    hy = lower_add(lower_sub(uy, outer_x), lower_and(ly, outer_x))
    crossings = lower_add(lower_and(ux, ly), lower_and(uy, lx))
    hi = lower_sub(lower_sub(lower_union((hx, hy, *rings)), lower_union(masks)), crossings)
    lo = lower_sub(lower_sub(lower_add(lx, ly), hi), lower_union(rear_masks))
    return ({k: lower_sub(lower[k], lo) for k in lower_KEYS},
            {k: lower_sub(upper[k], hi) for k in lower_KEYS}, set(posts), control_owners)


def lower_envelope():
    rear_top = 23 + 80 * math.sin(math.radians(49))
    shape = table_box(0, 600, 0, 320, -2, 18) - table_box(2, 598, 2, 318, 2, 102)
    shape += table_box(153.55, 446.45, 0, 2, 18, rear_top)
    shape = table_valid(shape, 'envelope')
    for x, y, ix, iy in ((0, 0, 2, -2), (600, 0, 598, -2),
                         (0, -320, 2, -318), (600, -320, 598, -318)):
        for px, py, radius in ((x, y, 3), (ix, iy, 1)):
            edges = [e for e in shape.edges()
                     if all(abs(p.X-px) < 1e-6 and abs(p.Y-py) < 1e-6 for p in table_edge_points(e))
                     and abs(table_edge_points(e)[-1].Z-table_edge_points(e)[0].Z) > 1]
            if len(edges) != 1:
                raise ValueError(('corner fillet edge', px, py, len(edges)))
            shape = table_valid(shape.solids()[0].fillet(radius, edges), 'plan fillet')
    def exterior(p):
        x, y = p.X, -p.Y
        tol = 1e-5
        if (((abs(x) < tol or abs(x-600) < tol) and 3-tol <= y <= 317+tol)
                or ((abs(y) < tol or abs(y-320) < tol) and 3-tol <= x <= 597+tol)):
            return True
        return any((x-cx)*(1 if cx == 3 else -1) <= tol
                   and (y-cy)*(1 if cy == 3 else -1) <= tol
                   and abs(math.hypot(x-cx, y-cy)-3) < tol
                   for cx, cy in ((3, 3), (597, 3), (3, 317), (597, 317)))
    edges = [e for e in shape.edges() if all(abs(p.Z+2) < 1e-6 and exterior(p) for p in table_edge_points(e))]
    if not edges:
        raise ValueError('No outside bottom fillet edges')
    shape = table_valid(shape.solids()[0].fillet(.8, edges), 'bottom fillet')
    shape -= table_box(37.25, 72.15, -.01, 2.01, 2, 18)
    for x in (32.75, 76.65):
        shape -= table_horizontal(x, -.01, 9.95, 1.8, 2.02)
    proof = {"ventilation_cells": VENTILATION_CELLS}
    if len(proof['ventilation_cells']) != 48:
        raise ValueError('Unexpected ventilation cells')
    for cell in proof['ventilation_cells']:
        wire = Wire.make_polygon([(x, .01, z) for x, z in cell['polygon_XZ']])
        shape -= Solid.extrude(Face(wire), (0, -2.02, 0))
    shape -= table_horizontal(101, 317.99, 10, 3.1, 2.02)
    inlet = INLET
    x, z = inlet['new_centre_XZ_mm']
    shape -= table_box(x-23.75, x+23.75, 0, 2, z-14, z+14)
    return table_valid(shape, 'cut envelope')


def lower_attach(shells, key, shape, label):
    if lower_empty(shape) or shape.volume <= 0:
        raise ValueError('Empty feature: ' + label)
    shells[key] = table_valid(shells[key] + shape, label + ' / ' + key)


def lower_cut(shells, cutter, label):
    hit = False
    for key in lower_KEYS:
        if not lower_empty(lower_and(shells[key], cutter)):
            shells[key] = table_valid(shells[key] - cutter, label + ' / ' + key)
            hit = True
    if not hit:
        raise ValueError('Cut missed all shells: ' + label)


def lower_build_shells():
    data = SHELL_DATA
    if len(data['schedules']['posts']) != 33:
        raise ValueError('Unexpected source post count')
    lower, upper, affected_posts, control_owners = lower_plan(data)
    envelope = lower_envelope()
    bottom_layer = table_box(0, 600, 0, 320, -2, 0)
    upper_and_wall = table_box(0, 600, 0, 320, 0, 100)
    shells = {}
    for key in lower_KEYS:
        low = lower_and(envelope, lower_and(lower[key], bottom_layer))
        high = lower_and(envelope, lower_and(upper[key], upper_and_wall))
        shells[key] = table_valid(lower_add(low, high), key + ' partition')
    for post in data['schedules']['posts']:
        x, y = post['centre_XY']
        f, c, pilot = post['foot'], post['core'], post['pilot']
        shape = table_cyl(x, y, *f['z'], f['bottom_radius'], f['top_radius'])
        shape += table_cyl(x, y, *c['z'], c['radius'])
        shape -= table_cyl(x, y, *pilot['z'], pilot['radius'])
        shape = lower_and(shape, table_box(0, 600, 0, 320, 0, 100))
        key = lower_owner(x, y, post['id'] not in lower_REAR)
        lower_attach(shells, key, shape, post['id'])
    fixed = [c for c in data['schedules']['controls'] if c['id'].endswith('-FIXED') or c['id'] == 'E01-fixed_cage']
    if len(fixed) != 49:
        raise ValueError('Unexpected fixed control count')
    for control in fixed:
        matrix = control['CSG'][1]
        key = control_owners.get(control['id'], lower_owner(matrix[0][3], matrix[1][3], True))
        lower_attach(shells, key, table_group(control['CSG']), control['id'])
    definition = {"devices": EQUIPMENT_DEVICES}
    for device in definition['devices']:
        if device['id'] not in ('PI', 'DAC', 'PSU'):
            raise ValueError('Unexpected mounting device: ' + device['id'])
        for x, old_y in device['mount_axes_XY']:
            y = old_y + 20
            radius, top = (5, 3) if device['id'] == 'PSU' else (3.5, 6)
            lower_attach(shells, lower_owner(x, y, True), table_cyl(x, y, 2, top, radius), device['id'])
            if device['id'] == 'PI':
                lower_cut(shells, table_cyl(x, y, 1, 6.01, 1), 'PI pilot')
            elif device['id'] == 'PSU':
                tool = (table_cyl(x, y, -2, 0, 3) + table_cyl(x, y, 0, 1.3, 3, 1.7)
                        + table_cyl(x, y, 1.3, 3.01, 1.7))
                lower_cut(shells, tool, 'PSU countersink')
    sensor_seat = jog_sensor_seat()
    for cx in (110, 490):
        cy = 165
        for angle in (150, 270, 30):
            x = cx + 31 * math.cos(math.radians(angle))
            y = cy - 31 * math.sin(math.radians(angle))
            lower_attach(shells, lower_owner(x, y, True), table_cyl(x, y, 2, 8, 5), 'jog mounting boss')
            lower_cut(shells, table_cyl(x, y, -2, 2.5, 2.4), 'jog head counterbore')
            lower_cut(shells, table_cyl(x, y, 2.5, 8.01, 1.45), 'jog screw clearance')
        seat = Pos(cx, -cy, 2) * Rot(0, 0, 60) * sensor_seat
        lower_attach(shells, lower_owner(cx, cy, True), seat, 'integral AS5048A sensor seat')
    if (len(CLAMP_STATIONS) != 14 or len(FOOT_STATIONS) != 18
            or len({s[0] for s in FOOT_STATIONS}) != 18):
        raise ValueError('Unexpected stations')
    clamp_ids = {s[0] for s in CLAMP_STATIONS}
    for identifier, x, y, axis in FOOT_STATIONS:
        if axis not in ('X', 'Y'):
            raise ValueError('Unexpected station axis: ' + identifier)
        if identifier in clamp_ids:
            for u in (-5, 5):
                px, py = (x+u, y) if axis == 'X' else (x, y+u)
                lower_cut(shells, table_cyl(px, py, -2, 2, 1.45), identifier + ' screw')
        for u in (-3, 3):
            for v in (-6.5, 6.5):
                px, py = (x+u, y+v) if axis == 'X' else (x+v, y+u)
                lower_cut(shells, table_cyl(px, py, -2, -.6, 1.65), identifier + ' socket')
    for key, shape in shells.items():
        table_valid(shape, key)
        shape.label = key + ' PETG integral-sensor-seat shell B26-LAP-build123d09 DRAFT'
    return shells

