def _esp_box(x0, y0, z0, x1, y1, z1):
    return Pos(x0, y0, z0) * Solid.make_box(x1 - x0, y1 - y0, z1 - z0)

def _esp_jaw(y, right=False, retraction=0.0):
    """Retraction is an inspection-only root-anchored shear, not FEA."""
    points = []
    for x, z in ESP_HOLDER['jaw_left_profile_xz']:
        fraction = min(1.0, (z - ESP_HOLDER['base_thickness']) / (10.5 - ESP_HOLDER['base_thickness']))
        x -= retraction * fraction
        points.append((ESP_BOARD['width'] - x if right else x, y, z))
    result = Solid.extrude(Face(Wire.make_polygon(points)), (0, ESP_HOLDER['crossbar_width_y'], 0))
    for at_front in [True, False]:
        outline = ESP_HOLDER['jaw_head_leadin_cut_polygon_xy']
        cut_points = []
        for x, dy in outline:
            x -= retraction
            yy = y + dy if at_front else y + ESP_HOLDER['crossbar_width_y'] - dy
            cut_points.append((ESP_BOARD['width'] - x if right else x, yy, ESP_HOLDER['jaw_head_leadin_cut_z'][0]))
        cut_height = ESP_HOLDER['jaw_head_leadin_cut_z'][1] - ESP_HOLDER['jaw_head_leadin_cut_z'][0]
        result = result.cut(Solid.extrude(Face(Wire.make_polygon(cut_points)), (0, 0, cut_height)))
    return result

def _esp_holder(retraction=0.0):
    if not 0 <= retraction <= 0.5:
        raise ValueError('Inspection jaw retraction must be within 0..0.5 mm')
    width = ESP_HOLDER['crossbar_width_y']
    ys = [v - width / 2 for v in ESP_HOLDER['crossbar_y_centres']]
    x0, x1 = ESP_HOLDER['spine_x_limits']
    pieces = [_esp_box(x0, ys[0], 0, x1, ys[-1] + width, ESP_HOLDER['base_thickness'])]
    for y in ys:
        x0, x1 = ESP_HOLDER['crossbar_x_limits']
        pieces.append(_esp_box(x0, y, 0, x1, y + width, ESP_HOLDER['base_thickness']))
        for x0, x1 in ESP_HOLDER['support_x_limits']:
            pieces.append(_esp_box(x0, y, ESP_HOLDER['base_thickness'], x1, y + width, ESP_BOARD['underside_z']))
        pieces.extend([_esp_jaw(y, retraction=retraction), _esp_jaw(y, right=True, retraction=retraction)])
    result = pieces[0].fuse(*pieces[1:]).clean()
    result.label = 'ESP-EDGE-01 holder - DRAFT printed PETG' if not retraction else 'INSPECTION ONLY - retracted jaws'
    return result

def _esp_references(lift=0.0):
    z = ESP_BOARD['underside_z'] + lift
    refs = {'ESP PCB - incomplete reference': _esp_box(0, 0, z, ESP_BOARD['width'], ESP_BOARD['length'], z + ESP_BOARD['thickness'])}
    for i, (x0, y0, x1, y1) in enumerate(ESP_HOLDER_DATA['inspection_references']['header_bottom_outline_aabb_xy'], 1):
        refs[f'Header {i} - conservative inspection envelope'] = _esp_box(x0, y0, z - ESP_BOARD['pins_below'], x1, y1, z)
    return refs

def _pcb_box(x0, y0, z0, x1, y1, z1):
    return Pos(x0, y0, z0) * Solid.make_box(x1 - x0, y1 - y0, z1 - z0)

def _pcb_place(row, shape):
    x, y = row['table_min']
    if row['orientation'] == 'long-X':
        shape = shape.rotate(Axis.Z, -90)
    else:
        shape = shape.mirror(Plane.XZ)
    return Pos(x, -y, PCB_HOLDER_DATA['floor_top_z']) * shape

def _pcb_holder(row, retraction=0.0):
    """Root-anchored in-plane shear is inspection-only, not solved elasticity."""
    if not 0 <= retraction <= 0.5:
        raise ValueError('Inspection retraction outside0..0.5mm')
    p = PCB_HOLDER_DATA['holder']
    width, length = (row['width'], row['length'])
    height = row['pcb_bottom_z'] - PCB_HOLDER_DATA['floor_top_z']
    base, margin = (p['base'], p['edge_margin_y'])
    pieces = []
    for right in (False, True):
        wing = [_pcb_box(-p['outside'], margin, 0, p['support_width'], length - margin, base), _pcb_box(0, margin, base, p['support_width'], length - margin, height)]
        for front in (True, False):
            root = p['beam_root_y'] if front else length - p['beam_root_y']
            head = p['head_centre_y'] if front else length - p['head_centre_y']
            wing.append(_pcb_box(*[p['root_x'][0], root - 1, base], p['root_x'][1], root + 1, height + 2.3))
            polygon = [(p['beam_outer_x'], root, height - 0.3), (p['beam_inner_x'], root, height - 0.3), (p['beam_inner_x'] - retraction, head, height - 0.3), (p['beam_outer_x'] - retraction, head, height - 0.3)]
            wing.append(Solid.extrude(Face(Wire.make_polygon(polygon)), (0, 0, 2.6)))
            profile = [(x - retraction, head - 1, height + z) for x, z in p['head_profile_offsets_xz']]
            jaw = Solid.extrude(Face(Wire.make_polygon(profile)), (0, 2, 0))
            for at_front in (True, False):
                points = [(x - retraction, head - 1 + dy if at_front else head + 1 - dy, height - 0.2) for x, dy in p['head_leadin_xy']]
                jaw = jaw.cut(Solid.extrude(Face(Wire.make_polygon(points)), (0, 0, 3)))
            wing.append(jaw)
        pieces.extend((Pos(width, 0, 0) * piece.mirror(Plane.YZ) if right else piece for piece in wing))
    for centre in (p['head_centre_y'], length - p['head_centre_y']):
        pieces.append(_pcb_box(-p['outside'], centre - 1, 0, width + p['outside'], centre + 1, base))
    result = pieces[0].fuse(*pieces[1:]).clean()
    if not result.is_valid or len(result.solids()) != 1:
        raise ValueError((row['id'], 'holder is not one valid solid'))
    result.label = GEOMETRY_REVISION + ' DRAFT ' + row['id'] + (' inspection' if retraction else ' integral holder')
    return result

def _pcb_references(row):
    height = row['pcb_bottom_z'] - PCB_HOLDER_DATA['floor_top_z']
    pcb = _pcb_box(0, 0, height, row['width'], row['length'], height + row['laminate'])
    upper = _pcb_box(0, 0, height + row['laminate'], row['width'], row['length'], height + row['laminate'] + row['above'])
    return {row['id'] + '-PCB-reference': _pcb_place(row, pcb), row['id'] + '-components-reference': _pcb_place(row, upper)}

def _build_retained_base():
    """Build the represented complete assembly; no viewer or export required."""
    shells = lower_build_shells()
    if set(shells) != {f'C{i:02d}' for i in range(1, 7)}:
        raise ValueError(f'Unexpected shell IDs: {sorted(shells)}')
    original_fasteners = enclosure_fastener_build()
    old_joint_ids = [key for key in original_fasteners if key.startswith('C07-')]
    if len(original_fasteners) != 197 or len(old_joint_ids) != 32:
        raise ValueError('REV_A fastener set does not contain the expected 32 C07 screws')
    for key in old_joint_ids:
        del original_fasteners[key]
    jog = jog_build()
    return {'Lower shells - printed PETG': shells, 'Lap bridges - printed PETG': lap_build_bridges(), 'Removable feet - printed PETG': lap_build_feet(), 'Flat panels and screen roof - printed PETG': enclosure_panel_build(), 'Control retainers - printed PETG': control_build_retainers(), 'Display toes - printed PETG': {name: Pos(0, 0, 5) * shape for name, shape in display_toe_build().items()}, 'Control caps - legacy mesh references': control_build_caps(), 'Controls - incomplete purchased references': control_build_references(), 'Equipment - incomplete purchased references': equipment_build(), 'Retained enclosure fasteners - incomplete references': original_fasteners, 'Lap fasteners and pads - incomplete references': lap_build_joint_hardware(), 'Static jogs - printed': jog['printed'], 'Static jogs - purchased references': jog['reference']}

def build():
    """Build current565-occurrence REV_B geometry11 without project-file inputs."""
    groups = _build_retained_base()
    shells = groups["Lower shells - printed PETG"]
    equipment = groups["Equipment - incomplete purchased references"]
    x0, y0, _ = ESP_HOLDER_DATA["installation"]["board_table_bounds"][0]
    esp_position = Pos(x0, -y0, ESP_HOLDER_DATA["installation"]["floor_top_z"])
    shells["C04"] = shells["C04"].fuse(esp_position * _esp_holder().mirror(Plane.XZ)).clean()
    del equipment[ESP_HOLDER_DATA["reference_ids"]["remove"]]
    for name, shape in zip(ESP_HOLDER_DATA["reference_ids"]["add"], _esp_references().values(), strict=True):
        equipment[name] = esp_position * shape.mirror(Plane.XZ)
    holders = {row["id"]: _pcb_place(row, _pcb_holder(row)) for row in PCB_HOLDER_DATA["boards"]}
    for owner in ("C04", "C06"):
        additions = [holders[row["id"]] for row in PCB_HOLDER_DATA["boards"] if row["owner"] == owner]
        shells[owner] = shells[owner].fuse(*additions).clean()
        shells[owner].label = "beatbreaker_REV_B_" + owner + " - integral controller holders"
        if not shells[owner].is_valid or len(shells[owner].solids()) != 1:
            raise ValueError("Invalid current printed shell: " + owner)
    for row in PCB_HOLDER_DATA["boards"]:
        del equipment[row["id"] + "-envelope"]
        equipment.update(_pcb_references(row))
    if len(groups) != 13 or sum(map(len, groups.values())) != 565:
        raise ValueError("Unexpected current REV_B population")
    return groups


def show_assembly(groups, port=3949):
    """Display actual shapes in the local standalone viewer."""
    from ocp_viewer import Camera, show

    colors = {
        "Lower shells - printed PETG": "#365340",
        "Lap bridges - printed PETG": "#365340",
        "Removable feet - printed PETG": "#365340",
        "Flat panels and screen roof - printed PETG": "#c6b49b",
        "Control retainers - printed PETG": "#365340",
        "Display toes - printed PETG": "#365340",
        "Control caps - legacy mesh references": "#594337",
        "Controls - incomplete purchased references": "#8a8a8a",
        "Equipment - incomplete purchased references": "#8a8a8a",
        "Retained enclosure fasteners - incomplete references": "#a0a0a0",
        "Lap fasteners and pads - incomplete references": "#909090",
        "Static jogs - printed": "#594337",
        "Static jogs - purchased references": "#8a8a8a",
    }
    names, shapes, palette = [], [], []
    for name, parts in groups.items():
        if parts:
            names.append("beatbreaker REV_B - " + name.replace("/", "_"))
            # Part IDs keep '/' from descriptive labels out of viewer paths.
            shapes.append({key.replace("/", "_"): value for key, value in parts.items()})
            palette.append(colors[name])
    show(*shapes, names=names, colors=palette, reset_camera=Camera.ISO, port=port)


def printed_parts(groups):
    """Select exactly 37 printed definitions/169 occurrences; references excluded."""
    families = {}

    def add(name, role, keys):
        keys = list(keys)
        if not keys or name in families:
            raise ValueError("Empty or duplicate printed family: " + name)
        families[name] = {"shape": groups[role][keys[0]], "quantity": len(keys),
                          "occurrences": [(role, key) for key in keys]}

    for role in ("Lower shells - printed PETG", "Flat panels and screen roof - printed PETG"):
        for key in groups[role]:
            add(key, role, [key])
    role = "Lap bridges - printed PETG"
    shifted = ("S05", "S06", "S07", "S08")
    add("bridge_A", role, (key for key in groups[role] if key not in shifted))
    add("bridge_B", role, shifted)
    for name, role in (("FT03", "Removable feet - printed PETG"),
                       ("display_toe", "Display toes - printed PETG")):
        add(name, role, groups[role])
    role = "Control retainers - printed PETG"
    for name, prefixes in (("button_retainer", ("B", "T")), ("pot_retainer", ("P",)),
                           ("fader_retainer", ("F",)), ("encoder_retainer", ("E",))):
        add(name, role, (key for key in groups[role] if key.startswith(prefixes)))
    role = "Static jogs - printed"
    for name, suffixes in (
        ("jog_P01_rotor", ("P01 platter and threaded rotor",)),
        ("jog_P02_carrier", ("P02 carrier B26-JOG-01",)),
        ("jog_P04_collar", ("P04 threaded retaining collar",)),
        ("jog_P07_collar", ("P07 threaded jam collar",)),
        ("jog_cover", ("P05 upper cover", "P06 lower cover")),
        ("jog_toe", ("P08 toe right", "P08 toe left")),
    ):
        add(name, role, (side + " " + suffix for suffix in suffixes for side in ("left", "right")))
    baseline = {row["owner"]: (row["CSG"][1][0][3], row["CSG"][1][1][3])
                for row in control_source_rows()}
    cap_keys = {kind: [] for kind in CAP_STL_BYTES}
    for row in CAP_INVENTORY:
        pose = row["pose"]
        owners = [owner for owner, (x, y) in baseline.items()
                  if math.isclose(x, pose[3] * 10, abs_tol=1e-6)
                  and math.isclose(y, -pose[7] * 10, abs_tol=1e-6)]
        if len(owners) != 1:
            raise ValueError("Ambiguous cap owner: " + row["id"])
        cap_keys[row["component"].split()[0]].append(owners[0] + "-CAP-REF")
    for kind, keys in cap_keys.items():
        add(kind, "Control caps - legacy mesh references", keys)
        families[kind]["stl_bytes"] = CAP_STL_BYTES[kind]
    expected = {(role, key) for role, parts in groups.items()
                if "printed" in role or role == "Control caps - legacy mesh references" for key in parts}
    observed = [identity for family in families.values() for identity in family["occurrences"]]
    if len(families) != 37 or len(observed) != 169 or len(set(observed)) != 169 or set(observed) != expected:
        raise ValueError("Printed definitions do not cover exactly the 169 intended occurrences")
    return families


def faceted_cap(kind):
    """Convert original mesh facets to a closed STEP solid, without analytic redesign."""
    from OCP.BRepBuilderAPI import BRepBuilderAPI_MakeFace, BRepBuilderAPI_MakePolygon, BRepBuilderAPI_Sewing

    raw = CAP_STL_BYTES[kind]
    if hashlib.sha256(raw).hexdigest() != CAP_ASSET_PROVENANCE[kind]["sha256"]:
        raise ValueError("Changed immutable cap mesh: " + kind)
    sewing = BRepBuilderAPI_Sewing()
    for values in struct.iter_unpack("<12fH", memoryview(raw)[84:]):
        points = [gp_Pnt(*values[i:i + 3]) for i in (3, 6, 9)]
        wire = BRepBuilderAPI_MakePolygon(*points, True).Wire()
        face = BRepBuilderAPI_MakeFace(wire).Face()
        if Face(face).area <= 0:
            raise ValueError("Degenerate cap facet: " + kind)
        sewing.Add(face)
    sewing.Perform()
    shells = Shape.cast(sewing.SewedShape()).shells()
    if len(shells) != 1 or not shells[0].is_manifold:
        raise ValueError("Cap mesh is not one closed shell: " + kind)
    solid = Solid(shells[0])
    if not solid.is_valid or solid.volume <= 0 or len(solid.faces()) != CAP_ASSET_PROVENANCE[kind]["triangles"]:
        raise ValueError("Invalid or incomplete faceted cap solid: " + kind)
    return solid


def step_assembly(groups):
    """Retain role/occurrence hierarchy; convert only mesh caps to faceted solids."""
    from build123d import Compound

    solids = {kind: faceted_cap(kind) for kind in CAP_STL_BYTES}
    represented = {**groups, "Control caps - legacy mesh references": control_build_caps(solids)}
    branches = []
    names = set()
    for role, parts in represented.items():
        leaves = []
        for key, part in parts.items():
            if not part.is_valid or not part.faces():
                raise ValueError("Invalid STEP occurrence: " + role + " / " + key)
            leaf = deepcopy(part)
            leaf.label = (role + " :: " + key).translate(str.maketrans(" .()", "____"))
            if leaf.label in names:
                raise ValueError("Duplicate STEP label: " + leaf.label)
            names.add(leaf.label)
            leaves.append(leaf)
        branches.append(Compound(label=role.translate(str.maketrans(" .()", "____")), children=leaves))
    return Compound(label="beatbreaker_REV_B_assembly", children=branches)


def export_release(directory, groups):
    """Write a fresh export set; completed files still require independent validation."""
    from OCP.BRepAlgoAPI import BRepAlgoAPI_Cut
    from OCP.BRepMesh import BRepMesh_IncrementalMesh
    from OCP.BRepTools import BRepTools, BRepTools_ReShape
    from OCP.StlAPI import StlAPI_Writer
    from OCP.collections import List_TopoDS_Shape
    from build123d import export_step

    directory = Path(directory)
    directory.mkdir(exist_ok=False)
    (directory / "STL").mkdir()
    parts = printed_parts(groups)
    result = {}
    for name, item in parts.items():
        path = directory / "STL" / (name + "_REV_B.stl")
        translation = None
        removed_wires = 0
        if "stl_bytes" in item:
            path.write_bytes(item["stl_bytes"])
        else:
            original = item["shape"]
            if not original.is_valid or len(original.solids()) != 1:
                raise ValueError("Invalid selected printed solid: " + name)
            shape = deepcopy(original)
            wires = [wire for face in shape.faces() for wire in face.wires() if not wire.is_closed]
            if wires:
                if (name, len(wires)) not in (("C01", 1), ("C02", 2)):
                    raise ValueError("Unexpected open mesh wire: " + name)
                reshaper = BRepTools_ReShape()
                for wire in wires:
                    reshaper.Remove(wire.wrapped)
                shape = Shape.cast(reshaper.Apply(shape.wrapped))
                for left, right in ((original, shape), (shape, original)):
                    operation = BRepAlgoAPI_Cut()
                    arguments, tools = List_TopoDS_Shape(), List_TopoDS_Shape()
                    arguments.Append(left.wrapped)
                    tools.Append(right.wrapped)
                    operation.SetArguments(arguments)
                    operation.SetTools(tools)
                    operation.SetNonDestructive(True)
                    operation.Build()
                    if not operation.IsDone() or operation.Shape().IsNull():
                        raise ValueError("Mesh topology-copy comparison failed: " + name)
                    difference = Shape.cast(operation.Shape())
                    if (not difference.is_empty and not difference.is_valid) or abs(difference.volume) > 1e-6:
                        raise ValueError("Mesh topology copy changed material: " + name)
                removed_wires = len(wires)
            if not shape.is_valid or any(not wire.is_closed for face in shape.faces() for wire in face.wires()):
                raise ValueError("Invalid mesh working copy: " + name)
            box = shape.bounding_box()
            translation = [1 - box.min.X, 1 - box.min.Y, 1 - box.min.Z]
            working = Pos(*translation) * shape
            BRepTools.Clean_s(working.wrapped)
            mesher = BRepMesh_IncrementalMesh(working.wrapped, 0.005, False, math.radians(5), True)
            if not mesher.IsDone() or mesher.GetStatusFlags() != 0:
                raise ValueError("Mesher failed: " + name)
            writer = StlAPI_Writer()
            writer.ASCIIMode = False
            if not writer.Write(working.wrapped, str(path)):
                raise ValueError("STL write failed: " + name)
        result[name] = {"filename": str(path), "quantity": item["quantity"],
                        "occurrences": item["occurrences"], "translation_mm": translation,
                        "removed_material_neutral_open_wires": removed_wires}
    step = directory / "beatbreaker_REV_B_assembly.step"
    if not export_step(step_assembly(groups), step):
        raise ValueError("STEP write failed")
    return {"stl": result, "step": str(step), "status": "WRITTEN; independent export checks required"}


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--view", action="store_true", help="send the assembly to the local viewer")
    parser.add_argument("--export", type=Path, metavar="DIR", help="after model approval, write all STL/STEP files to a fresh directory")
    args = parser.parse_args()
    groups = build()
    print("beatbreaker REV_B (geometry B26-LAP-build123d11; approved unpowered trial only):",
          [(name, len(parts)) for name, parts in groups.items()], flush=True)
    if args.view:
        show_assembly(groups)
    if args.export is not None:
        result = export_release(args.export, groups)
        print("Wrote", len(result["stl"]), "STLs and STEP; independent validation required.", flush=True)

if __name__ == "__main__":
    main()
